CORE_02 = """# PHASE CORE-02: Dependency Injection Container

## Tier
Core (Foundational Infrastructure)

## Resolves
Finding 8 — Zero implementation blocker. This blueprint is directly implementable.

## Component Name
Reactive DI Container — `SovereignStack\\Core\\Container`

## Description
A PSR-11-compliant dependency injection container with constructor autowiring via reflection, compiler passes for build-time optimization, and circular-dependency detection at resolution time. Every Hub blueprint is blocked on this component existing.

## Architectural Design

```php
namespace SovereignStack\\Core\\Container;

use Psr\\Container\\ContainerInterface as PsrContainerInterface;

interface ContainerInterface extends PsrContainerInterface {
    public function bind(string $abstract, mixed $concrete = null, bool $shared = false): void;
    public function singleton(string $abstract, mixed $concrete = null): void;
    public function instance(string $abstract, object $instance): void;
    public function make(string $abstract, array $parameters = []): mixed;
    public function addCompilerPass(CompilerPassInterface $pass): void;
    public function compile(): void;
}

final class Container implements ContainerInterface {
    private array $definitions = [];
    private array $resolved = [];
    private array $resolving = [];
    private bool $compiled = false;

    public function make(string $abstract, array $parameters = []): mixed {
        if (isset($this->resolved[$abstract])) return $this->resolved[$abstract];
        if (\\in_array($abstract, $this->resolving, true)) {
            throw new CircularDependencyException([...$this->resolving, $abstract]);
        }
        $this->resolving[] = $abstract;
        try {
            $definition = $this->definitions[$abstract] ?? null;
            $concrete = $definition?->concrete ?? $abstract;
            $instance = match(true) {
                $concrete instanceof \\Closure => $concrete($this, $parameters),
                \\is_string($concrete) && \\class_exists($concrete) => $this->autowire($concrete, $parameters),
                default => throw new NotFoundException("No binding or class found for [{$abstract}]."),
            };
            if ($definition?->shared) $this->resolved[$abstract] = $instance;
            return $instance;
        } finally {
            \\array_pop($this->resolving);
        }
    }
    // ... (Full implementation as specified in previous delivery)
}
```

## CI Verification Criteria
- 100% branch coverage on `make()`, `autowire()`, and `compile()`.
- No dependency added beyond `psr/container`.
"""

